# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">NAMAZIN DIŞINDAKİ FARZLAR (HAZIRLIK ŞARTLARI - 6 MADDE)</text>\n  <rect x="20" y="48" width="210" height="88" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="70" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">1. Hadesten Taharet</text>\n  <text x="125" y="94" text-anchor="middle" font-size="11" fill="#1e3a8a">Abdestsizlik durumunu abdest,</text>\n  <text x="125" y="112" text-anchor="middle" font-size="11" fill="#1e3a8a">gusül veya teyemmümle gidermek.</text>\n\n  <rect x="245" y="48" width="210" height="88" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="350" y="70" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">2. Necasetten Taharet</text>\n  <text x="350" y="94" text-anchor="middle" font-size="11" fill="#1e3a8a">Beden, elbise ve namaz kılınacak</text>\n  <text x="350" y="112" text-anchor="middle" font-size="11" fill="#1e3a8a">yeri maddi kirlerden temizlemek.</text>\n\n  <rect x="470" y="48" width="210" height="88" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="575" y="70" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">3. Setr-i Avret</text>\n  <text x="575" y="94" text-anchor="middle" font-size="11" fill="#1e3a8a">Namazda örtülmesi gereken</text>\n  <text x="575" y="112" text-anchor="middle" font-size="11" fill="#1e3a8a">vücut bölümlerini örtmek.</text>\n\n  <rect x="20" y="150" width="210" height="88" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="125" y="172" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">4. İstikbâl-i Kıble</text>\n  <text x="125" y="196" text-anchor="middle" font-size="11" fill="#14532d">Namazı Mekke\'deki Kâbe</text>\n  <text x="125" y="214" text-anchor="middle" font-size="11" fill="#14532d">(kıble) yönüne dönerek kılmak.</text>\n\n  <rect x="245" y="150" width="210" height="88" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="350" y="172" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">5. Vakit</text>\n  <text x="350" y="196" text-anchor="middle" font-size="11" fill="#14532d">Kılınacak namazın vaktinin</text>\n  <text x="350" y="214" text-anchor="middle" font-size="11" fill="#14532d">girmiş olması (ezanla bildirilir).</text>\n\n  <rect x="470" y="150" width="210" height="88" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="575" y="172" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">6. Niyet</text>\n  <text x="575" y="196" text-anchor="middle" font-size="11" fill="#14532d">Hangi namazın kılınacağını</text>\n  <text x="575" y="214" text-anchor="middle" font-size="11" fill="#14532d">Allah rızası için kalben bilmek.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">NAMAZIN İÇİNDEKİ FARZLAR (RÜKÜNLER - 6 MADDE)</text>\n  <rect x="20" y="48" width="210" height="88" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="125" y="70" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b45309">1. İftitah Tekbiri</text>\n  <text x="125" y="94" text-anchor="middle" font-size="11" fill="#78350f">Namaza başlarken «Allahu ekber»</text>\n  <text x="125" y="112" text-anchor="middle" font-size="11" fill="#78350f">diyerek başlangıç tekbiri almak.</text>\n\n  <rect x="245" y="48" width="210" height="88" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="350" y="70" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b45309">2. Kıyam</text>\n  <text x="350" y="94" text-anchor="middle" font-size="11" fill="#78350f">Namazda Kur\'an okunacak</text>\n  <text x="350" y="112" text-anchor="middle" font-size="11" fill="#78350f">süre boyunca ayakta durmak.</text>\n\n  <rect x="470" y="48" width="210" height="88" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="575" y="70" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b45309">3. Kıraat</text>\n  <text x="575" y="94" text-anchor="middle" font-size="11" fill="#78350f">Kıyamda iken Kur\'an-ı Kerim\'den</text>\n  <text x="575" y="112" text-anchor="middle" font-size="11" fill="#78350f">ayet veya sure okumak.</text>\n\n  <rect x="20" y="150" width="210" height="88" rx="8" fill="#faf5ff" stroke="#9333ea" stroke-width="1.5"/>\n  <text x="125" y="172" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#7e22ce">4. Rükû</text>\n  <text x="125" y="196" text-anchor="middle" font-size="11" fill="#581c87">Eller diz kapaklarına gelecek</text>\n  <text x="125" y="214" text-anchor="middle" font-size="11" fill="#581c87">şekilde sırt düz olarak eğilmek.</text>\n\n  <rect x="245" y="150" width="210" height="88" rx="8" fill="#faf5ff" stroke="#9333ea" stroke-width="1.5"/>\n  <text x="350" y="172" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#7e22ce">5. Secde</text>\n  <text x="350" y="196" text-anchor="middle" font-size="11" fill="#581c87">Alın, burun, eller, dizler ve ayak</text>\n  <text x="350" y="214" text-anchor="middle" font-size="11" fill="#581c87">parmaklarıyla iki kez yere kapanmak.</text>\n\n  <rect x="470" y="150" width="210" height="88" rx="8" fill="#faf5ff" stroke="#9333ea" stroke-width="1.5"/>\n  <text x="575" y="172" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#7e22ce">6. Ka\'de-i Ahîre</text>\n  <text x="575" y="196" text-anchor="middle" font-size="11" fill="#581c87">Namazın sonunda Tahiyyat</text>\n  <text x="575" y="214" text-anchor="middle" font-size="11" fill="#581c87">duasını okuyacak kadar oturmak.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">BEŞ VAKİT NAMAZIN REKÂT SAYILARI TABLOSU (TOPLAM 40 REKÂT)</text>\n  <rect x="20" y="48" width="660" height="190" rx="8" fill="#ecfeff" stroke="#0891b2" stroke-width="1.5"/>\n  <text x="350" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Vakit Namazları (17 Farz + 20 Sünnet + 3 Vitir = 40 Rekât)</text>\n  <text x="350" y="102" text-anchor="middle" font-size="12" font-weight="bold" fill="#164e63">• SABAH NAMAZI (4 Rekât): 2 Rekât Sünnet + 2 Rekât Farz</text>\n  <text x="350" y="128" text-anchor="middle" font-size="12" font-weight="bold" fill="#164e63">• ÖĞLE NAMAZI (10 Rekât): 4 İlk Sünnet + 4 Farz + 2 Son Sünnet</text>\n  <text x="350" y="154" text-anchor="middle" font-size="12" font-weight="bold" fill="#164e63">• İKİNDİ NAMAZI (8 Rekât): 4 Rekât Sünnet + 4 Rekât Farz</text>\n  <text x="350" y="180" text-anchor="middle" font-size="12" font-weight="bold" fill="#164e63">• AKŞAM NAMAZI (5 Rekât): 3 Rekât Farz + 2 Rekât Sünnet</text>\n  <text x="350" y="206" text-anchor="middle" font-size="12" font-weight="bold" fill="#164e63">• YATSI NAMAZI (10 Rekât + 3 Vitir): 4 İlk Sünnet + 4 Farz + 2 Son Sünnet + 3 Vitir (Vacip)</text>\n  <text x="350" y="228" text-anchor="middle" font-size="11" fill="#155e75">Her kıyam, kıraat, rükû ve iki secdeden oluşan bölüme 1 rekât denir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
